use vstd::prelude::*;

verus! {
    fn numpy_flip(m: Vec<f32>) -> (result: Vec<f32>)
        requires
            // No preconditions on the input vector
        ensures
            // The output vector has the same length as the input vector
            result.len() == m.len() &&
            // For every valid index i, the element at position i in the output
            // equals the element at position n - 1 - i in the input
            forall|i: nat| (i < m.len() as nat) ==> (result[i as usize] == m[(m.len() as nat - 1 - i) as usize])
    {
        let n = m.len();
        let mut result = vec![0.0; n]; // Initialize result vector with the same length as m

        let mut i: usize = 0;
        while i < n
            invariant
                i <= n,
                result.len() == n,
                forall|j: nat| (j < i as nat) ==> (result[j as usize] == m[(n as nat - 1 - j) as usize]),
            decreases n - i,
        {
            result[i] = m[n - 1 - i]; // Flip the elements
            i += 1;
        }
        
        result // Return the flipped vector
    }
}

